window.TASK_BANKS[56] = {"version":1,"topicId":56,"tasks":[{"id":"56.1","codeLang":"python","answer":"['Учёт']\n7\nNone","answerLang":"text","explanation":"Workbook создаёт книгу с одним листом. active выбирает лист, title меняет имя, B2 соответствует второй строке и второму столбцу. В пустой ячейке value равно None, а не нулю или пустой строке.","verified":"3.14","wrong":["['Sheet']\n7\n0","['Учёт']\nNone\nNone"]},{"id":"56.2","codeLang":"python","answer":"from openpyxl import Workbook\ndef make_catalog(rows):\n    book = Workbook()\n    page = book.active\n    page.title = 'Остатки'\n    page.append(['Артикул', 'Количество'])\n    for sku, qty in rows:\n        page.append([sku, qty])\n        page.cell(page.max_row, 1).data_type = 's'\n    return book","answerLang":"python","explanation":"Артикул — идентификатор, его нельзя превращать в число. openpyxl обычно распознаёт строку с = как формулу; data_type=s явно сохраняет её текстом. Проверка повторно открывает сохранённую книгу: недостаточно похожего print или списка вместо Workbook.","verified":"3.14","check":{"append":"from io import BytesIO as _BytesIO\nfrom openpyxl import Workbook as _Workbook, load_workbook as _load\ndef _bytes(book):\n    stream = _BytesIO()\n    book.save(stream)\n    return stream.getvalue()\ndef _source(rows, sheet='Остатки', header=('Артикул','Количество'), notes=False):\n    book = _Workbook()\n    page = book.active\n    page.title = sheet\n    page.append(header)\n    for row in rows:\n        page.append(row)\n        if isinstance(row[0],str):\n            page.cell(page.max_row,1).data_type='s'\n    if notes:\n        extra=book.create_sheet('Примечания')\n        extra['A1']='Сохранить'\n        extra['A2']='=2+3'\n        from openpyxl.styles import Font\n        extra['A1'].font=Font(italic=True)\n    return _bytes(book)\n\nfrom copy import deepcopy as _deepcopy\nfor _rows in [[('0012',3),('=1+1',0),('чай',4)], [], [('x',0),('x',2)]]:\n    _before=_deepcopy(_rows)\n    _book=make_catalog(_rows)\n    assert isinstance(_book,_Workbook), 'Верните Workbook'\n    _reopened=_load(_BytesIO(_bytes(_book)))\n    assert _reopened.sheetnames==['Остатки']\n    _page=_reopened['Остатки']\n    assert list(_page.values)==[('Артикул','Количество')]+[tuple(row) for row in _rows], 'Сохраните заголовок, порядок и значения'\n    assert all(_page.cell(i,1).data_type=='s' for i in range(2,len(_rows)+2)), 'Артикулы должны быть текстом, не формулами'\n    assert _rows==_before, 'Входной список изменился'\nprint('OK')","expect":"OK"}},{"id":"56.3","codeLang":"python","answer":"12 n\n0012 s\n=A1*2 f","answerLang":"text","explanation":"n обозначает числовую ячейку, s — строковую, f — формулу. В value формулы хранится её выражение. Формат показа числа не превращает его в текстовый идентификатор и не восстанавливает потерянные ведущие нули.","verified":"3.14","wrong":["12 n\n12 n\n24 n","12 s\n0012 s\n=A1*2 s"]},{"id":"56.4","codeLang":"python","answer":"from io import BytesIO\nfrom openpyxl import load_workbook\ndef read_inventory(data):\n    book = load_workbook(BytesIO(data), data_only=False)\n    page = book['Остатки']\n    return [(sku, qty) for sku, qty in page.iter_rows(min_row=2, max_col=2, values_only=True) if sku is not None]","answerLang":"python","explanation":"iter_rows по умолчанию возвращает Cell, а values_only=True — их значения. min_row=2 пропускает заголовок. Проверка пустоты по артикулу не выбрасывает полезную запись с количеством 0. BytesIO позволяет прочитать учебную книгу без обращения к личным файлам.","verified":"3.14","check":{"append":"from io import BytesIO as _BytesIO\nfrom openpyxl import Workbook as _Workbook, load_workbook as _load\ndef _bytes(book):\n    stream = _BytesIO()\n    book.save(stream)\n    return stream.getvalue()\ndef _source(rows, sheet='Остатки', header=('Артикул','Количество'), notes=False):\n    book = _Workbook()\n    page = book.active\n    page.title = sheet\n    page.append(header)\n    for row in rows:\n        page.append(row)\n        if isinstance(row[0],str):\n            page.cell(page.max_row,1).data_type='s'\n    if notes:\n        extra=book.create_sheet('Примечания')\n        extra['A1']='Сохранить'\n        extra['A2']='=2+3'\n        from openpyxl.styles import Font\n        extra['A1'].font=Font(italic=True)\n    return _bytes(book)\n\nfor _rows,_expected in [([('0012',0),(None,None),('B',7)],[('0012',0),('B',7)]),([],[]),([('A',1),('A',2)],[('A',1),('A',2)])]:\n    _data=_source(_rows)\n    _got=read_inventory(_data)\n    assert type(_got) is list and _got==_expected, f'Ожидалось {_expected}, получено {_got}'\nprint('OK')","expect":"OK"}},{"id":"56.5","codeLang":"python","answer":"from copy import copy\ndef format_prices(book):\n    page = book['Цены']\n    for cell in page[1]:\n        font = copy(cell.font)\n        font.bold = True\n        cell.font = font\n    for row in page.iter_rows(min_row=2, min_col=2, max_col=2):\n        row[0].number_format = '0.00'\n    page.freeze_panes = 'A2'\n    page.auto_filter.ref = f'A1:B{page.max_row}'","answerLang":"python","explanation":"Числовой формат управляет отображением, а не значением. Копия Font позволяет изменить bold и сохранить italic/цвет. freeze_panes и auto_filter задают настройки для Excel; фильтр не удаляет строки и не сортирует их в Python.","verified":"3.14","check":{"append":"from io import BytesIO as _BytesIO\nfrom openpyxl import Workbook as _Workbook, load_workbook as _load\ndef _bytes(book):\n    stream = _BytesIO()\n    book.save(stream)\n    return stream.getvalue()\ndef _source(rows, sheet='Остатки', header=('Артикул','Количество'), notes=False):\n    book = _Workbook()\n    page = book.active\n    page.title = sheet\n    page.append(header)\n    for row in rows:\n        page.append(row)\n        if isinstance(row[0],str):\n            page.cell(page.max_row,1).data_type='s'\n    if notes:\n        extra=book.create_sheet('Примечания')\n        extra['A1']='Сохранить'\n        extra['A2']='=2+3'\n        from openpyxl.styles import Font\n        extra['A1'].font=Font(italic=True)\n    return _bytes(book)\n\nfrom openpyxl.styles import Font as _Font\nfor _rows in [[],[('чай',12),('кофе',3.5)]]:\n    _book=_load(_BytesIO(_source(_rows,sheet='Цены',header=('Товар','Цена'))))\n    _page=_book['Цены']\n    _page['A1'].font=_Font(italic=True,color='FF123456')\n    _values=list(_page.values)\n    format_prices(_book)\n    _page=_load(_BytesIO(_bytes(_book)))['Цены']\n    assert list(_page.values)==_values, 'Оформление изменило значения'\n    assert _page['A1'].font.bold and _page['B1'].font.bold\n    assert _page['A1'].font.italic and _page['A1'].font.color.rgb=='FF123456', 'Сохраните остальные свойства шрифта'\n    assert _page.freeze_panes=='A2' and _page.auto_filter.ref==f'A1:B{len(_rows)+1}'\n    assert all(_page.cell(i,2).number_format=='0.00' for i in range(2,len(_rows)+2))\nprint('OK')","expect":"OK"}},{"id":"56.6","codeLang":"python","answer":"=SUM(B1:B2)\nNone","answerLang":"text","explanation":"openpyxl записывает формулу, но не вычисляет её. data_only=True читает последний сохранённый результат из файла. У новой формулы кэша ещё нет, поэтому получено None. Не сохраняйте поверх исходника книгу, загруженную только ради чтения кэша: так можно потерять формулы.","verified":"3.14","wrong":["=SUM(B1:B2)\n10","10\n10"]},{"id":"56.7","codeLang":"python","answer":"from io import BytesIO\nfrom openpyxl import load_workbook\ndef add_totals(data):\n    book = load_workbook(BytesIO(data), data_only=False)\n    source = book['Данные']\n    page = book.create_sheet('Итог')\n    page.append(['Количество строк', source.max_row - 1])\n    total = f\"=SUM('Данные'!B2:B{source.max_row})\" if source.max_row > 1 else 0\n    page.append(['Всего штук', total])\n    output = BytesIO()\n    book.save(output)\n    return output.getvalue()","answerLang":"python","explanation":"data_only=False сохраняет выражения формул. Новая версия записывается в отдельный поток; исходные bytes не перезаписываются. Для пустой таблицы используется 0 вместо обратного диапазона B2:B1. Эти гарантии относятся к описанной учебной книге; сложные файлы Excel с макросами, рисунками и связями требуют отдельной проверки и копии.","verified":"3.14","check":{"append":"from io import BytesIO as _BytesIO\nfrom openpyxl import Workbook as _Workbook, load_workbook as _load\ndef _bytes(book):\n    stream = _BytesIO()\n    book.save(stream)\n    return stream.getvalue()\ndef _source(rows, sheet='Остатки', header=('Артикул','Количество'), notes=False):\n    book = _Workbook()\n    page = book.active\n    page.title = sheet\n    page.append(header)\n    for row in rows:\n        page.append(row)\n        if isinstance(row[0],str):\n            page.cell(page.max_row,1).data_type='s'\n    if notes:\n        extra=book.create_sheet('Примечания')\n        extra['A1']='Сохранить'\n        extra['A2']='=2+3'\n        from openpyxl.styles import Font\n        extra['A1'].font=Font(italic=True)\n    return _bytes(book)\n\nfor _rows in [[],[('A',0),('0012',4)]]:\n    _data=_source(_rows,sheet='Данные',notes=True)\n    _result=add_totals(_data)\n    assert type(_result) is bytes, 'Верните XLSX как bytes'\n    _book=_load(_BytesIO(_result),data_only=False)\n    assert _book.sheetnames==['Данные','Примечания','Итог'], 'Сохраните прежние листы и добавьте Итог'\n    assert list(_book['Данные'].values)==[('Артикул','Количество')]+_rows\n    assert _book['Примечания']['A2'].value=='=2+3' and _book['Примечания']['A1'].font.italic\n    _page=_book['Итог']\n    assert _page['A1'].value=='Количество строк' and _page['B1'].value==len(_rows)\n    assert _page['A2'].value=='Всего штук'\n    assert _page['B2'].value==(f\"=SUM('Данные'!B2:B{len(_rows)+1})\" if _rows else 0), 'Проверьте диапазон формулы и пустой случай'\nprint('OK')","expect":"OK"}},{"id":"56.8","codeLang":"python","answer":"from pathlib import Path\nfrom openpyxl import Workbook\ndef save_new_report(path, title):\n    book = Workbook()\n    page = book.active\n    page.title = 'Отчёт'\n    page['A1'] = title\n    page['A1'].data_type = 's'\n    with Path(path).open('xb') as stream:\n        book.save(stream)","answerLang":"python","explanation":"Режим xb создаёт новый бинарный файл и отказывает при существующем пути. Workbook.save сам по себе обычно перезаписывает файл. Ошибка диска после создания может оставить частичный новый файл; атомарность здесь не обещается. export_file на платформе делает снимок готового файла для скачивания, а не сохраняет всё состояние контейнера.","verified":"3.14","check":{"append":"from io import BytesIO as _BytesIO\nfrom openpyxl import Workbook as _Workbook, load_workbook as _load\ndef _bytes(book):\n    stream = _BytesIO()\n    book.save(stream)\n    return stream.getvalue()\ndef _source(rows, sheet='Остатки', header=('Артикул','Количество'), notes=False):\n    book = _Workbook()\n    page = book.active\n    page.title = sheet\n    page.append(header)\n    for row in rows:\n        page.append(row)\n        if isinstance(row[0],str):\n            page.cell(page.max_row,1).data_type='s'\n    if notes:\n        extra=book.create_sheet('Примечания')\n        extra['A1']='Сохранить'\n        extra['A2']='=2+3'\n        from openpyxl.styles import Font\n        extra['A1'].font=Font(italic=True)\n    return _bytes(book)\n\nfrom pathlib import Path as _Path\nimport tempfile as _tempfile\nwith _tempfile.TemporaryDirectory() as _folder:\n    _path=_Path(_folder)/'new.xlsx'\n    save_new_report(_path,'=не формула')\n    _page=_load(_path).active\n    assert _page.title=='Отчёт' and _page['A1'].value=='=не формула' and _page['A1'].data_type=='s'\n    _before=_path.read_bytes()\n    try:\n        save_new_report(_path,'Перезаписано')\n    except FileExistsError:\n        pass\n    else:\n        raise AssertionError('Существующий файл нельзя перезаписывать')\n    assert _path.read_bytes()==_before, 'Существующая книга изменилась'\n    import os as _os\n    import io as _io\n    import builtins as _bi\n    _race = _Path(_folder) / 'race.xlsx'\n    _io_open, _os_open, _builtin_open = _io.open, _os.open, _bi.open\n    _injected = [False]\n\n    def _other_writer_arrives(path):\n        if (not _injected[0] and isinstance(path, (str, _os.PathLike))\n                and _Path(path) == _race):\n            _injected[0] = True\n            # Original io.open: never call our wrappers recursively.\n            with _io_open(_race, 'xb') as file:\n                file.write(b'OTHER WRITER')\n\n    def _racing_io_open(path, mode='r', *args, **kwargs):\n        if any(flag in mode for flag in 'wax+'):\n            _other_writer_arrives(path)\n        return _io_open(path, mode, *args, **kwargs)\n\n    def _racing_os_open(path, flags, *args, **kwargs):\n        if flags & (_os.O_WRONLY | _os.O_RDWR | _os.O_CREAT | _os.O_TRUNC | _os.O_APPEND):\n            _other_writer_arrives(path)\n        return _os_open(path, flags, *args, **kwargs)\n\n    def _racing_builtin_open(path, mode='r', *args, **kwargs):\n        if any(flag in mode for flag in 'wax+'):\n            _other_writer_arrives(path)\n        return _builtin_open(path, mode, *args, **kwargs)\n    _io.open, _os.open, _bi.open = _racing_io_open, _racing_os_open, _racing_builtin_open\n    try:\n        try:\n            save_new_report(_race, 'Новая книга')\n        except FileExistsError:\n            assert _injected[0] and _race.read_bytes() == b'OTHER WRITER', 'Не меняйте файл другого создателя'\n        else:\n            assert not _injected[0], 'Между проверкой exists и записью появился файл: нужен исключительный режим создания'\n    finally:\n        _io.open, _os.open, _bi.open = _io_open, _os_open, _builtin_open\nprint('OK')","expect":"OK"}},{"id":"56.9","codeLang":"python","answer":"from io import BytesIO\nfrom openpyxl import Workbook, load_workbook\ndef clean_stock(data):\n    source = load_workbook(BytesIO(data), data_only=False)['Выгрузка']\n    book = Workbook()\n    clean = book.active\n    clean.title = 'Очищено'\n    clean.append(['Артикул', 'Количество', 'Цена, коп.'])\n    rejected = book.create_sheet('Отклонено')\n    rejected.append(['Строка', 'Причина'])\n    for number, cells in enumerate(source.iter_rows(min_row=2, max_col=3), 2):\n        sku, qty, price = (cell.value for cell in cells)\n        if cells[0].data_type != 's' or not isinstance(sku, str) or not sku.strip():\n            reason = 'артикул'\n        elif type(qty) is not int or not 0 <= qty <= 10000:\n            reason = 'количество'\n        elif type(price) is not int or not 0 <= price <= 10000:\n            reason = 'цена'\n        else:\n            clean.append([sku.strip(), qty, price])\n            clean.cell(clean.max_row, 1).data_type = 's'\n            continue\n        rejected.append([number, reason])\n    output = BytesIO()\n    book.save(output)\n    return output.getvalue()","answerLang":"python","explanation":"Чистый отчёт не должен молча угадывать артикул по числу или превращать пропуск в ноль. Валидация отдельно проверяет тип и допустимый диапазон. Журнал сохраняет номер строки, чтобы исправить первоисточник. Ноль допустим, bool отсекается через type(value) is int. Текстовый артикул с = записывается как текст, а формула во входной ячейке отбрасывается. Деньги хранятся целыми копейками, поэтому не нужен float.","verified":"3.14","hint":"Разделите проверку строк и запись результата. Возьмите по одному отказу каждого типа, настоящий ноль и текстовый артикул с ведущими нулями.","check":{"append":"from io import BytesIO as _BytesIO\nfrom openpyxl import Workbook as _Workbook, load_workbook as _load\ndef _bytes(book):\n    stream = _BytesIO()\n    book.save(stream)\n    return stream.getvalue()\ndef _source(rows, sheet='Остатки', header=('Артикул','Количество'), notes=False):\n    book = _Workbook()\n    page = book.active\n    page.title = sheet\n    page.append(header)\n    for row in rows:\n        page.append(row)\n        if isinstance(row[0],str):\n            page.cell(page.max_row,1).data_type='s'\n    if notes:\n        extra=book.create_sheet('Примечания')\n        extra['A1']='Сохранить'\n        extra['A2']='=2+3'\n        from openpyxl.styles import Font\n        extra['A1'].font=Font(italic=True)\n    return _bytes(book)\n\n_cases=[\n([(' 0012 ',0,12),('B',2,0),('=1+1',3,4)],[('0012',0,12),('B',2,0),('=1+1',3,4)],[]),\n([(None,1,1),(' ',2,3),(123,2,3),('x',True,3),('y',-1,3),('z',1,'2'),('a',1,10001)],[],[(2,'артикул'),(3,'артикул'),(4,'артикул'),(5,'количество'),(6,'количество'),(7,'цена'),(8,'цена')]),\n([],[],[]),\n([('A',1.5,2),('A',1,2.5),('A','2',3),('A',1,False),('A',1,2),('A',2,3)],[('A',1,2),('A',2,3)],[(2,'количество'),(3,'цена'),(4,'количество'),(5,'цена')]),\n([(None,-1,-1),('X',-1,-1),('Y',1,-1)],[],[(2,'артикул'),(3,'количество'),(4,'цена')]),\n([('edge',10000,10000),('bad',10001,2),('bad',1,10001)],[('edge',10000,10000)],[(3,'количество'),(4,'цена')])]\nfor _rows,_good,_bad in _cases:\n    _data=_source(_rows,sheet='Выгрузка',header=('Артикул','Количество','Цена, коп.'))\n    _result=clean_stock(_data)\n    assert type(_result) is bytes\n    _book=_load(_BytesIO(_result),data_only=False)\n    assert _book.sheetnames==['Очищено','Отклонено']\n    assert list(_book['Очищено'].values)==[('Артикул','Количество','Цена, коп.')]+_good, 'Проверьте принятые строки, нули, порядок и типы'\n    assert list(_book['Отклонено'].values)==[('Строка','Причина')]+_bad, 'Укажите исходный номер строки и первую причину отказа'\n    assert all(_book['Очищено'].cell(i,1).data_type=='s' for i in range(2,len(_good)+2))\n_raw=_Workbook();_raw.active.title='Выгрузка';_raw.active.append(['Артикул','Количество','Цена, коп.']);_raw.active.append(['=1+1',1,2])\n_book=_load(_BytesIO(clean_stock(_bytes(_raw))))\nassert list(_book['Отклонено'].values)==[('Строка','Причина'),(2,'артикул')], 'Формула не является текстовым артикулом'\nprint('OK')","expect":"OK"}},{"id":"56.10","codeLang":"python","answer":"from io import BytesIO\nfrom copy import copy\nfrom openpyxl import load_workbook\ndef build_stock_report(data):\n    book = load_workbook(BytesIO(data), data_only=False)\n    source = book['Очищено']\n    page = book.create_sheet('Отчёт')\n    page.append(['Артикул', 'Количество', 'Цена, коп.', 'Стоимость, коп.'])\n    for sku, qty, price in source.iter_rows(min_row=2, max_col=3, values_only=True):\n        number = page.max_row + 1\n        page.append([sku, qty, price, f'=B{number}*C{number}'])\n        page.cell(number, 1).data_type = 's'\n    last = page.max_row\n    page.append(['Итого', None, None, f'=SUM(D2:D{last})' if last > 1 else 0])\n    for cell in page[1]:\n        font = copy(cell.font)\n        font.bold = True\n        cell.font = font\n    for row in page.iter_rows(min_row=2, min_col=3, max_col=4):\n        for cell in row:\n            cell.number_format = '#,##0'\n    page.freeze_panes = 'A2'\n    page.auto_filter.ref = f'A1:D{last}'\n    output = BytesIO()\n    book.save(output)\n    return output.getvalue()","answerLang":"python","explanation":"Отчёт создаётся в новой версии, а исходные листы остаются доступны. Формулы ссылаются на свою строку; итог не должен включать сам себя. Формат #,##0 показывает целые копейки, не меняя значения. Фильтр охватывает данные, но не итог. Новые формулы не имеют вычисленного кэша: None при data_only=True не означает ошибку формулы. Для просмотра сохраните возвращённые bytes в свой новый .xlsx и откройте копию в Excel/LibreOffice либо явно экспортируйте её на платформе.","verified":"3.14","hint":"Проверьте отдельно обычную и пустую таблицу. После повторного открытия сравните формулы, старые листы и настройки просмотра; не ждите вычислений от openpyxl.","check":{"append":"from io import BytesIO as _BytesIO\nfrom openpyxl import Workbook as _Workbook, load_workbook as _load\ndef _bytes(book):\n    stream = _BytesIO()\n    book.save(stream)\n    return stream.getvalue()\ndef _source(rows, sheet='Остатки', header=('Артикул','Количество'), notes=False):\n    book = _Workbook()\n    page = book.active\n    page.title = sheet\n    page.append(header)\n    for row in rows:\n        page.append(row)\n        if isinstance(row[0],str):\n            page.cell(page.max_row,1).data_type='s'\n    if notes:\n        extra=book.create_sheet('Примечания')\n        extra['A1']='Сохранить'\n        extra['A2']='=2+3'\n        from openpyxl.styles import Font\n        extra['A1'].font=Font(italic=True)\n    return _bytes(book)\n\nfor _rows in [[],[('0012',0,8),('=1+1',2,3),('кофе',7,25)],[('A',1,1)]]:\n    _data=_source(_rows,sheet='Очищено',header=('Артикул','Количество','Цена, коп.'),notes=True)\n    _result=build_stock_report(_data)\n    assert type(_result) is bytes\n    _book=_load(_BytesIO(_result),data_only=False)\n    assert _book.sheetnames==['Очищено','Примечания','Отчёт']\n    assert list(_book['Очищено'].values)==[('Артикул','Количество','Цена, коп.')]+_rows\n    assert _book['Примечания']['A2'].value=='=2+3' and _book['Примечания']['A1'].font.italic\n    _page=_book['Отчёт'];_last=len(_rows)+1\n    assert tuple(c.value for c in _page[1])==('Артикул','Количество','Цена, коп.','Стоимость, коп.')\n    for _i,_row in enumerate(_rows,2):\n        assert tuple(_page.cell(_i,c).value for c in range(1,4))==_row\n        assert _page.cell(_i,1).data_type=='s'\n        _formula=_page.cell(_i,4).value\n        assert isinstance(_formula,str) and _formula.replace(' ','').replace('$','').upper() in {f'=B{_i}*C{_i}',f'=C{_i}*B{_i}'}, 'Формула стоимости должна ссылаться на B/C своей строки'\n    assert _page.cell(_last+1,1).value=='Итого'\n    _total=_page.cell(_last+1,4).value\n    assert _total==(f'=SUM(D2:D{_last})' if _rows else 0), 'Не включайте итоговую ячейку в её собственный диапазон'\n    assert all(c.font.bold for c in _page[1])\n    assert _page.freeze_panes=='A2' and _page.auto_filter.ref==f'A1:D{_last}'\n    assert all(_page.cell(r,c).number_format=='#,##0' for r in range(2,_last+2) for c in (3,4))\nprint('OK')","expect":"OK"}}]};
